import {disposeObject} from './dispose.js';
import {enrichCity} from './urban-detail.js';
import {cityScenery} from './city-scenery.js';
import * as T from 'three';
import {box,cylinder,sign,mat,tree,person,vehicle} from './models.js';
import {createGarage} from './garage.js';
import {block,roads,hospitalPoint} from './roads.js';
export function cityDensity(minute){const h=(minute/60)%24;return h<6?.28:h<9?1:h<16?.72:h<19?1:h<22?.64:.38;}
export function neighborhood(scene){const root=new T.Group();scene.add(root);box(root,930,1,770,'#829375',60,-.6,0);const lamps=[],citizens=[],hydrants=[],traffic=[],buildings=[];
for(const r of roads.filter(r=>!r.ramp)){const dx=r.b[0]-r.a[0],dz=r.b[1]-r.a[1],len=Math.hypot(dx,dz),x=(r.a[0]+r.b[0])/2,z=(r.a[1]+r.b[1])/2,yaw=Math.atan2(dx,dz);for(const [w,y,color]of (r.trail?[[9,-.01,'#8c896a'],[6,.045,'#ae9a74']]:r.ramp?[[22,.04,'#b2b6ac'],[18,.16,'#555f62']]:[[13,.04,'#b2b6ac'],[9,.16,'#555f62']])){const m=box(root,w,.13,len+.2,color,x,y,z);m.rotation.y=yaw;}if(len>25&&!r.trail){for(let d=5;d<len;d+=9){const m=box(root,.12,.025,3,'#e5dfc3',r.a[0]+dx*d/len,.25,r.a[1]+dz*d/len);m.rotation.y=yaw;}const tx=x+dz/len*6,tz=z-dx/len*6;cylinder(root,.09,.12,6,'#5b6c6d',tx,3,tz,6);lamps.push(box(root,.7,.15,.4,new T.MeshStandardMaterial({color:'#eee6c6',emissive:'#ffe5b0',emissiveIntensity:.1}),tx,6,tz));const h=new T.Group();h.position.set(x-dz/len*6,0,z+dx/len*6);root.add(h);cylinder(h,.28,.32,1.05,'#be3d2d',0,.6,0);box(h,.85,.24,.25,'#dc5541',0,.8,0);hydrants.push(h);if(!r.name.includes('(simulation)')){const label=sign(root,r.name,Math.min(20,len*.7),1.1,x+dz/len*5.6,.3,z-dx/len*5.6,'#a9b1a6','#3c5154');label.rotation.x=-Math.PI/2;label.rotation.z=yaw-Math.PI/2;}}}
// One joined ribbon prevents cracks and overlapping rectangular shoulders in the bend.
const ramp=roads.filter(r=>r.ramp),rampPoints=ramp.length?[ramp[0].a,...ramp.map(r=>r.b)]:[];
if(rampPoints.length){
 const normals=rampPoints.slice(1).map((p,i)=>{const a=rampPoints[i],d=Math.hypot(p[0]-a[0],p[1]-a[1]);return [(p[1]-a[1])/d,-(p[0]-a[0])/d];});
 const joins=rampPoints.map((p,i)=>{const a=normals[Math.max(0,i-1)],b=normals[Math.min(normals.length-1,i)],den=1+a[0]*b[0]+a[1]*b[1];return [(a[0]+b[0])/den,(a[1]+b[1])/den];});
 const ribbon=(halfWidth,y,color,offset=0)=>{const v=[];const edge=(i,side)=>{const taper=i===rampPoints.length-1?.5:1,n=joins[i],p=rampPoints[i],w=(offset+side*halfWidth)*taper;return[p[0]+n[0]*w,y,p[1]+n[1]*w];};for(let i=1;i<rampPoints.length;i++){const a=edge(i-1,-1),b=edge(i-1,1),c=edge(i,1),d=edge(i,-1);v.push(...a,...c,...b,...a,...d,...c);}const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(v,3));geo.computeVertexNormals();const mesh=new T.Mesh(geo,new T.MeshStandardMaterial({color,side:T.DoubleSide,roughness:1}));mesh.receiveShadow=true;mesh.name='Raccord continu bretelle Est';root.add(mesh);};
 ribbon(11,.105,'#b2b6ac');ribbon(9,.225,'#555f62');ribbon(.65,.29,'#8e9a80');for(const side of[-1,1]){ribbon(.065,.26,'#e8e5ce',side*4.5);ribbon(.075,.27,'#e8e5ce',side*8.5);}
}
for(const [i,b]of block.buildings.entries()){const points=b.points,shape=new T.Shape();points.forEach(([x,z],j)=>j?shape.lineTo(x,-z):shape.moveTo(x,-z));const height=Math.min(27,Math.max(3,b.levels*3));const geo=new T.ExtrudeGeometry(shape,{depth:height,bevelEnabled:false});geo.rotateX(-Math.PI/2);const m=new T.Mesh(geo,mat(['#d7cdb7','#c4bcab','#d2bca5'][i%3]));m.castShadow=true;m.receiveShadow=true;root.add(m);buildings.push(m);const roof=new T.Mesh(new T.ShapeGeometry(shape),mat('#657174'));roof.rotation.x=-Math.PI/2;roof.position.y=height+.05;m.add(roof);for(let j=0;j<points.length-1;j++){const a=points[j],c=points[j+1],len=Math.hypot(c[0]-a[0],c[1]-a[1]);if(len<3)continue;const yaw=Math.atan2(c[0]-a[0],c[1]-a[1]);for(let d=2;d<len-1;d+=3.5)for(let y=1.9;y<height-.5;y+=3){const w=box(m,.12,1.3,1.25,'#314b55',a[0]+(c[0]-a[0])*d/len,y,a[1]+(c[1]-a[1])*d/len);w.rotation.y=yaw;}}}
const beach=cityScenery(root);enrichCity(root,block,roads);const {station,roofs}=createGarage(root);// Marked apron and separated one-way approach / departure lanes at the CH.
box(root,13,.09,64,'#778583',372,.12,-122);
for(let i=0;i<4;i++){const z=-141+i*10;for(const x of[373.5,376.5])box(root,.08,.02,7.5,'#dcdcc0',x,.18,z);}
for(const z of[-143,-125,-106]){box(root,.12,.02,2,'#dedcc4',367,.18,z);box(root,1,.02,.13,'#dedcc4',367,.18,z+.8);}
const hospital=new T.Group();hospital.position.set(390,0,-120);root.add(hospital);box(hospital,21,8,35,'#deded1',0,4,0);box(hospital,22,.4,36,'#768e92',0,8.2,0);for(let z=-12;z<=12;z+=4)box(hospital,.12,2,2.5,'#365964',-10.6,4,z);sign(hospital,'CH • URGENCES',16,1.6,0,6,17.6,'#397682');box(hospital,8,.2,9,'#7b8d8d',-13,4.4,0);for(let z of[-13,4])box(hospital,.15,2.6,z<0?6:14,'#92b8ba',-10.6,1.4,z);sign(root,'DÉPOSE VSAV',12,1,-1+hospitalPoint[0],.35,hospitalPoint[1],'#477a84').rotation.x=-Math.PI/2;
const usable=roads.filter(r=>!r.trail&&!r.name.includes('(simulation)')&&Math.hypot(r.a[0]-r.b[0],r.a[1]-r.b[1])>15);for(let i=0;i<40;i++){const r=usable[i%usable.length],p=person(root,0,0,['#aa705a','#516c85','#887f54'][i%3]);citizens.push({model:p,road:r,phase:i/40,densityRank:(i+.5)/40});}for(let i=0;i<20;i++){const r=usable[(i*3)%usable.length],car=vehicle(root,'VLCG',['#7d9391','#c5b99b','#55737e','#9d6656'][i%4]);car.userData.beacons.forEach(b=>b.visible=false);car.scale.setScalar(.85);const dx=r.b[0]-r.a[0],dz=r.b[1]-r.a[1],len=Math.hypot(dx,dz);car.position.set(r.a[0]+dx*i/20-dz/len*(r.express?5:2),0,r.a[1]+dz*i/20+dx/len*(r.express?5:2));car.rotation.y=Math.atan2(dx,dz);traffic.push({model:car,road:r,progress:i/20,densityRank:(i+.5)/20});}for(let i=0;i<16;i++)tree(root,-20+(i%4)*7,-95+Math.floor(i/4)*10,1,i%4);
// Apply the same road clearance to every tree source, including decorative rows.
for(const plant of [...root.children])if(plant.userData.treeClearance){
 const {x,z}=plant.position;
 const blocked=roads.some(r=>{const dx=r.b[0]-r.a[0],dz=r.b[1]-r.a[1],t=Math.max(0,Math.min(1,((x-r.a[0])*dx+(z-r.a[1])*dz)/(dx*dx+dz*dz||1)));return Math.hypot(x-r.a[0]-t*dx,z-r.a[1]-t*dz)<(r.trail?4.5:6.5)+plant.userData.treeClearance;});
 if(blocked)disposeObject(plant);
}
const fireBuilding=new T.Group();scene.add(fireBuilding);fireBuilding.userData={width:8,depth:8,height:4};return{root,fireBuilding,buildings,lamps,citizens,traffic,station,roofs,hydrants,block,hospitalPoint,beach};}
